def find_python_files_with_routes(root_dir):
    patterns = ['@app.route', '@route', 'submit', '/v1/', '.py']
    results = []
    for dirpath, dirnames, filenames in os.walk(root_dir):
        if 'site-packages' in dirpath or 'venv' in dirpath:
